class Solution:
    def maximumMexArray(self, nums: List[int]) -> List[int]:
        res = []
        i, n = 0, len(nums)
        while i < n:
            seen = set()
            mex = best = 0
            bk = i
            for j in range(i, n):
                seen.add(nums[j])
                while mex in seen:
                    mex += 1
                if mex > best:
                    best = mex
                    bk = j + 1
            res.append(best)
            i = bk
        return res

