class Solution:
    def maximumMexArray(self, nums: List[int]) -> List[int]:
        n = len(nums)
        maxV = max(nums) + 2
        tot = [0] * maxV
        for x in nums:
            tot[x] += 1
        win = [0] * maxV
        res = []
        start = 0
        while start < n:
            m = 0
            while m < maxV and tot[m] > 0:
                m += 1
            if m == 0:
                res.append(0)
                tot[nums[start]] -= 1
                start += 1
                continue
            cover, j = 0, start
            while cover < m:
                v = nums[j]
                if v < m:
                    if win[v] == 0:
                        cover += 1
                    win[v] += 1
                j += 1
            res.append(m)
            for i in range(start, j):
                tot[nums[i]] -= 1
                if nums[i] < m:
                    win[nums[i]] -= 1
            start = j
        return res

