class Solution {
public:
    vector<int> maximumMexArray(vector<int>& nums) {
        int n = nums.size();
        int maxV = *max_element(nums.begin(), nums.end()) + 2;
        vector<int> tot(maxV, 0), win(maxV, 0), res;
        for (int x : nums) tot[x]++;
        int start = 0;
        while (start < n) {
            int m = 0;
            while (m < maxV && tot[m] > 0) m++;
            if (m == 0) {
                res.push_back(0);
                tot[nums[start++]]--;
                continue;
            }
            int cover = 0, j = start;
            while (cover < m) {
                int v = nums[j];
                if (v < m) { if (win[v]++ == 0) cover++; }
                j++;
            }
            res.push_back(m);
            for (int i = start; i < j; i++) {
                tot[nums[i]]--;
                if (nums[i] < m) win[nums[i]]--;
            }
            start = j;
        }
        return res;
    }
};

