class Solution {
    public int[] maximumMexArray(int[] nums) {
        int n = nums.length;
        int maxV = 0;
        for (int x : nums) maxV = Math.max(maxV, x);
        maxV += 2;
        int[] tot = new int[maxV], win = new int[maxV];
        for (int x : nums) tot[x]++;
        int[] tmp = new int[n];
        int rc = 0, start = 0;
        while (start < n) {
            int m = 0;
            while (m < maxV && tot[m] > 0) m++;
            if (m == 0) {
                tmp[rc++] = 0;
                tot[nums[start++]]--;
                continue;
            }
            int cover = 0, j = start;
            while (cover < m) {
                int v = nums[j];
                if (v < m) { if (win[v]++ == 0) cover++; }
                j++;
            }
            tmp[rc++] = m;
            for (int i = start; i < j; i++) {
                tot[nums[i]]--;
                if (nums[i] < m) win[nums[i]]--;
            }
            start = j;
        }
        int[] res = new int[rc];
        System.arraycopy(tmp, 0, res, 0, rc);
        return res;
    }
}

